<template><div class="app-container"><el-row :gutter="10"><el-col :span="2"><el-button v-hasPermi="['library:vip:operation']" type="primary" @click="show('open')">人工开通/续期</el-button></el-col><el-col :span="2"><el-button v-hasPermi="['library:vip:operation']" type="warning" @click="show('compensate')">会员补偿</el-button></el-col></el-row><el-table :data="rows" border class="mt16"><el-table-column prop="userId" label="用户编号"/><el-table-column prop="sourceType" label="来源"/><el-table-column prop="sourceBizNo" label="业务编号"/><el-table-column prop="oldExpireTime" label="原到期时间"/><el-table-column prop="newExpireTime" label="新到期时间"/><el-table-column prop="giftPoints" label="赠送积分"/></el-table><el-dialog :title="mode==='open'?'人工开通/续期':'会员补偿'" :visible.sync="visible"><el-form :model="form" label-width="110px"><el-form-item label="用户编号" required><el-input-number v-model="form.userId" :min="1"/></el-form-item><el-form-item v-if="mode==='open'" label="会员套餐" required><el-select v-model="form.planId"><el-option v-for="p in plans" :key="p.id" :label="`${p.planName}（赠送${p.giftPoints}积分）`" :value="p.id"/></el-select></el-form-item><el-form-item v-else label="补偿天数" required><el-input-number v-model="form.days" :min="1"/></el-form-item><el-form-item label="赠送积分"><el-tag>{{ mode==='open'?selectedGift:0 }}</el-tag></el-form-item><el-form-item label="业务编号" required><el-input v-model="form.bizNo"/></el-form-item><el-form-item label="操作原因" required><el-input v-model="form.reason" type="textarea"/></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="submit">确定</el-button></span></el-dialog></div></template>
<script>import { listEntitlements,listVipPlans,openVip,compensateVip } from '@/api/library/vip';export default{name:'LibraryVipEntitlement',data(){return{rows:[],plans:[],mode:'open',visible:false,form:{}}},computed:{selectedGift(){const p=this.plans.find(x=>x.id===this.form.planId);return p?p.giftPoints:0}},created(){this.load();listVipPlans({status:'0',pageSize:100}).then(r=>{this.plans=r.rows||[]})},methods:{load(){listEntitlements({pageNum:1,pageSize:100}).then(r=>{this.rows=r.rows||[]})},show(mode){this.mode=mode;this.form={userId:1,days:1,bizNo:'',reason:''};this.visible=true},submit(){if(!this.form.bizNo||!this.form.reason)return this.$modal.msgError('业务编号和操作原因不能为空');(this.mode==='open'?openVip:compensateVip)(this.form).then(()=>{this.$modal.msgSuccess('操作成功');this.visible=false;this.load()})}}}</script><style scoped>.mt16{margin-top:16px}</style>
